import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import { Palette, Zap, Moon, Sun, Layout, Code, Sparkles, Shield } from 'lucide-react';

function App() {
  const [darkMode, setDarkMode] = useState(false);

  // Initialiser le mode sombre depuis le localStorage ou les préférences système
  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

    if (savedTheme === 'dark' || (!savedTheme && prefersDark)) {
      setDarkMode(true);
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, []);

  // Basculer entre mode sombre et clair
  const toggleDarkMode = () => {
    const newDarkMode = !darkMode;
    setDarkMode(newDarkMode);

    if (newDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  };

  // Fonctionnalités de l'application
  const features = [
    {
      icon: <Palette className="text-primary-500" size={24} />,
      title: "Palette de couleurs complète",
      description: "Accédez à une palette de couleurs personnalisée avec des nuances pour chaque couleur."
    },
    {
      icon: <Moon className="text-secondary-500" size={24} />,
      title: "Mode sombre/clair",
      description: "Basculez facilement entre les modes sombre et clair avec persistance des préférences."
    },
    {
      icon: <Layout className="text-accent-500" size={24} />,
      title: "Design responsive",
      description: "Interface entièrement responsive qui s'adapte à tous les appareils."
    },
    {
      icon: <Zap className="text-primary-500" size={24} />,
      title: "Performances optimisées",
      description: "Code optimisé pour des performances exceptionnelles et un chargement rapide."
    },
    {
      icon: <Code className="text-secondary-500" size={24} />,
      title: "Code propre",
      description: "Code React et Tailwind CSS bien structuré, facile à maintenir et à étendre."
    },
    {
      icon: <Sparkles className="text-accent-500" size={24} />,
      title: "Animations fluides",
      description: "Animations et transitions subtiles pour une expérience utilisateur agréable."
    }
  ];

  // Sections de couleur
  const colorSections = [
    { name: "Primaire", color: "primary", code: "bg-primary-500" },
    { name: "Secondaire", color: "secondary", code: "bg-secondary-500" },
    { name: "Accentuation", color: "accent", code: "bg-accent-500" },
    { name: "Neutre", color: "neutral", code: "bg-neutral-500" }
  ];

  return (
    <div className="min-h-screen bg-white dark:bg-neutral-950 text-neutral-900 dark:text-neutral-100 transition-colors duration-300">
      <Header darkMode={darkMode} toggleDarkMode={toggleDarkMode} />

      <main className="container mx-auto px-4 py-8">
        {/* Hero Section */}
        <section className="text-center py-12 md:py-16">
          <div className="inline-flex items-center px-4 py-2 rounded-full bg-primary-100 dark:bg-primary-900/30 text-primary-700 dark:text-primary-300 mb-4">
            <Sparkles size={16} className="mr-2" />
            <span className="text-sm font-medium">React + Tailwind CSS</span>
          </div>
          <h1 className="text-4xl md:text-6xl font-bold mb-6">
            Application <span className="text-primary-600 dark:text-primary-400">Moderne</span>
            <br />
            avec Mode <span className="text-secondary-600 dark:text-secondary-400">Sombre/Clair</span>
          </h1>
          <p className="text-lg md:text-xl text-neutral-600 dark:text-neutral-400 max-w-3xl mx-auto mb-8">
            Une application React complète avec Tailwind CSS, palette de couleurs personnalisée, 
            et basculement fluide entre les modes sombre et clair.
          </p>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <button className="px-8 py-3 bg-primary-600 hover:bg-primary-700 text-white font-semibold rounded-lg transition-colors duration-200 shadow-lg hover:shadow-xl">
              Commencer maintenant
            </button>
            <button className="px-8 py-3 border-2 border-neutral-300 dark:border-neutral-700 hover:border-primary-500 dark:hover:border-primary-500 font-semibold rounded-lg transition-colors duration-200">
              En savoir plus
            </button>
          </div>
        </section>

        {/* Palette de couleurs */}
        <section className="py-12">
          <h2 className="text-3xl font-bold mb-2 text-center">Palette de couleurs</h2>
          <p className="text-neutral-600 dark:text-neutral-400 text-center mb-10 max-w-2xl mx-auto">
            Notre palette de couleurs complète inclut des nuances pour chaque couleur, optimisées 
            pour les modes clair et sombre.
          </p>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-12">
            {colorSections.map((section) => (
              <div key={section.color} className="bg-white dark:bg-neutral-900 rounded-xl shadow-lg dark:shadow-neutral-800/30 p-6">
                <h3 className="text-xl font-semibold mb-4">{section.name}</h3>
                <div className="space-y-3">
                  {[50, 100, 200, 300, 400, 500, 600, 700, 800, 900].map((shade) => (
                    <div key={shade} className="flex items-center">
                      <div 
                        className={`w-10 h-10 rounded-lg mr-3 border border-neutral-200 dark:border-neutral-700 bg-${section.color}-${shade}`}
                      />
                      <div className="flex-1">
                        <div className="flex justify-between">
                          <span className="text-sm font-medium text-neutral-700 dark:text-neutral-300">
                            {section.color}-{shade}
                          </span>
                          <span className="text-xs text-neutral-500">
                            {shade}
                          </span>
                        </div>
                        <div className="text-xs text-neutral-500 mt-1">
                          {/* Vous pouvez ajouter le code hex ici si nécessaire */}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </section>

        {/* Fonctionnalités */}
        <section className="py-12">
          <h2 className="text-3xl font-bold mb-2 text-center">Fonctionnalités principales</h2>
          <p className="text-neutral-600 dark:text-neutral-400 text-center mb-10 max-w-2xl mx-auto">
            Découvrez les fonctionnalités clés de cette application React moderne avec Tailwind CSS.
          </p>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {features.map((feature, index) => (
              <div 
                key={index} 
                className="bg-white dark:bg-neutral-900 rounded-xl shadow-lg dark:shadow-neutral-800/30 p-6 hover:shadow-xl dark:hover:shadow-neutral-800/50 transition-shadow duration-300"
              >
                <div className="inline-flex p-3 rounded-lg bg-neutral-100 dark:bg-neutral-800 mb-4">
                  {feature.icon}
                </div>
                <h3 className="text-xl font-semibold mb-2">{feature.title}</h3>
                <p className="text-neutral-600 dark:text-neutral-400">{feature.description}</p>
              </div>
            ))}
          </div>
        </section>

        {/* Démontration mode sombre/clair */}
        <section className="py-12">
          <div className="bg-gradient-to-r from-primary-500/10 to-secondary-500/10 dark:from-primary-500/5 dark:to-secondary-500/5 rounded-2xl p-8 md:p-12">
            <div className="flex flex-col md:flex-row items-center justify-between">
              <div className="md:w-1/2 mb-8 md:mb-0">
                <h2 className="text-3xl font-bold mb-4">Mode Sombre & Clair</h2>
                <p className="text-neutral-600 dark:text-neutral-400 mb-6">
                  L'application inclut un basculement fluide entre les modes sombre et clair. 
                  Les préférences sont sauvegardées pour votre prochaine visite.
                </p>
                <div className="flex items-center space-x-4">
                  <button
                    onClick={toggleDarkMode}
                    className="flex items-center space-x-2 px-6 py-3 bg-primary-600 hover:bg-primary-700 text-white font-semibold rounded-lg transition-colors duration-200"
                  >
                    {darkMode ? (
                      <>
                        <Sun size={20} />
                        <span>Mode clair</span>
                      </>
                    ) : (
                      <>
                        <Moon size={20} />
                        <span>Mode sombre</span>
                      </>
                    )}
                  </button>
                  <div className="text-sm text-neutral-500">
                    Actuellement en mode <span className="font-semibold">{darkMode ? 'sombre' : 'clair'}</span>
                  </div>
                </div>
              </div>

              <div className="md:w-1/2 flex justify-center">
                <div className="relative">
                  <div className="w-64 h-64 rounded-2xl bg-white dark:bg-neutral-800 shadow-2xl overflow-hidden border border-neutral-200 dark:border-neutral-700">
                    {/* Simulation d'interface */}
                    <div className="h-8 flex items-center px-4 border-b border-neutral-200 dark:border-neutral-700">
                      <div className="flex space-x-2">
                        <div className="w-3 h-3 rounded-full bg-red-400"></div>
                        <div className="w-3 h-3 rounded-full bg-yellow-400"></div>
                        <div className="w-3 h-3 rounded-full bg-green-400"></div>
                      </div>
                    </div>
                    <div className="p-4">
                      <div className="flex items-center mb-4">
                        <div className="w-10 h-10 rounded-lg bg-primary-500 mr-3"></div>
                        <div>
                          <div className="h-3 w-24 bg-neutral-300 dark:bg-neutral-600 rounded mb-2"></div>
                          <div className="h-2 w-16 bg-neutral-200 dark:bg-neutral-700 rounded"></div>
                        </div>
                      </div>
                      <div className="space-y-2">
                        <div className="h-3 w-full bg-neutral-200 dark:bg-neutral-700 rounded"></div>
                        <div className="h-3 w-3/4 bg-neutral-200 dark:bg-neutral-700 rounded"></div>
                        <div className="h-3 w-5/6 bg-neutral-200 dark:bg-neutral-700 rounded"></div>
                      </div>
                      <div className="flex justify-between mt-6">
                        <div className="h-8 w-20 bg-primary-500 rounded-lg"></div>
                        <div className="h-8 w-20 bg-neutral-300 dark:bg-neutral-600 rounded-lg"></div>
                      </div>
                    </div>
                  </div>

                  {/* Badge mode */}
                  <div className="absolute -top-3 -right-3 px-4 py-1 rounded-full bg-primary-500 text-white font-medium text-sm">
                    {darkMode ? 'Mode sombre' : 'Mode clair'}
                  </div>
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* Footer */}
        <footer className="mt-16 pt-8 border-t border-neutral-200 dark:border-neutral-800">
          <div className="flex flex-col md:flex-row justify-between items-center">
            <div className="flex items-center space-x-2 mb-4 md:mb-0">
              <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-primary-500 to-secondary-500 flex items-center justify-center">
                <span className="text-white font-bold">R</span>
              </div>
              <div>
                <h3 className="font-bold text-lg">ReactUI</h3>
                <p className="text-sm text-neutral-500">Application moderne avec Tailwind CSS</p>
              </div>
            </div>

            <div className="text-center md:text-right">
              <p className="text-neutral-600 dark:text-neutral-400">
                &copy; {new Date().getFullYear()} ReactUI. Tous droits réservés.
              </p>
              <p className="text-sm text-neutral-500 mt-1">
                Construit avec React, Tailwind CSS et ❤️
              </p>
            </div>
          </div>
        </footer>
      </main>
    </div>
  );
}

export default App;
